def resumen_nulos_vacios(df, nombre):
    print(f"Valores nulos o vacíos: {nombre}")

    expresiones = []

    for campo in df.schema.fields:
        columna = F.col(f"`{campo.name}`")
        condicion = columna.isNull()

        if campo.dataType.simpleString() == "string":
            condicion = condicion | (F.trim(columna) == "")

        expresiones.append(
            F.sum(F.when(condicion, 1).otherwise(0)).alias(campo.name)
        )

    return df.agg(*expresiones)

display(resumen_nulos_vacios(df_cliente, "Clientes Bronze"))

